mapper.select:
SELECT id,serial_id,sku_id,operation_id,kind,transfer_id,from_epoch,context_hash,state,claim_epoch,attempts
FROM serial_recovery_intent WHERE enterprise_id=#{e} AND warehouse_id=#{w}
AND state IN ('PENDING','RUNNING') AND next_attempt_at <= #{now}
ORDER BY next_attempt_at,id LIMIT 1 FOR UPDATE SKIP LOCKED

SELECT id,serial_id AS serialId,sku_id AS skuId,operation_id AS operationId,kind,transfer_id AS transferId,
  from_epoch AS fromEpoch,state,claim_epoch AS claimEpoch,attempts,last_error AS lastError,created_at
FROM serial_recovery_intent WHERE enterprise_id=#{e} AND warehouse_id=#{w}
AND state=#{state}
AND (created_at < #{page.time} OR (created_at=#{page.time} AND id < #{page.id}))
ORDER BY created_at DESC,id DESC LIMIT #{page.fetchLimit}
